import{_ as o,o as r,c as e,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Работа с Bot","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/working-with-bots.md","filePath":"ru/guides/working-with-bots.md","lastUpdated":1792323081000}'),s={name:"ru/guides/working-with-bots.md"};function l(d,t,n,i,h,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="работа-с-bot" tabindex="-1">Работа с Bot <a class="header-anchor" href="#работа-с-bot" aria-label="Permalink to &quot;Работа с Bot&quot;">​</a></h1><p><a href="./quick-start.html">Быстрый старт</a> помогает запустить Bot; эта страница — о том, как работать с ним хорошо: что делегировать, как формулировать, где должны жить правила и когда один Bot должен стать двумя. Дальше идёт справочник конфигурации: создание Bot и каждая вкладка его страницы деталей.</p><h2 id="что-делегировать" tabindex="-1">Что делегировать <a class="header-anchor" href="#что-делегировать" aria-label="Permalink to &quot;Что делегировать&quot;">​</a></h2><p>Задача хорошо подходит для Bot, когда выполняются три условия:</p><ul><li><strong>Ясный результат.</strong> Вы можете сказать, что должно существовать, когда работа закончена, — файл, сообщение, таблица.</li><li><strong>Достижимые источники.</strong> Задействованные файлы, сайты или диалоги Bot действительно может достать: они загружены в его рабочее пространство, подключены как канал или сервис либо общедоступны.</li><li><strong>Проверяемый итог.</strong> Вы с одного взгляда понимаете, верен ли результат, поэтому проверка остаётся дешёвой.</li></ul><p>Даже когда все три условия выполнены, начинайте с режима «только чтение»: пусть Bot сначала читает и организует, просмотрите несколько результатов, затем выдавайте больше.</p><h2 id="сформулируите-запрос" tabindex="-1">Сформулируйте запрос <a class="header-anchor" href="#сформулируите-запрос" aria-label="Permalink to &quot;Сформулируйте запрос&quot;">​</a></h2><p>Хороший запрос отвечает на пять вопросов: результат, источник, ограничения, формат, контрольная точка. Таблица — в <a href="./quick-start.html#шаг-4-даите-ему-задачу">Быстром старте</a>; вот как разница выглядит на практике.</p><div class="warning custom-block"><p class="custom-block-title">Расплывчато</p><blockquote><p>Поглядывай за новостями про технологии и присылай мне всё интересное.</p></blockquote></div><p>Нет источника (какие сайты или репозитории?), нет времени доставки, а «интересное» — суждение, которое Bot должен выносить за вас. Каждый дайджест превращается в подбрасывание монетки.</p><p><strong>Вместо этого:</strong></p><div class="tip custom-block"><p class="custom-block-title">Конкретно</p><blockquote><p>Каждый будний день в 8 утра делай сводку релизов и заметных issue за последние 24 часа по репозиториям, за которыми я слежу, и присылай их мне одним дайджестом. Для каждого пункта указывай источник; если что-то неточно, так и скажи, а не угадывай.</p></blockquote></div><div class="warning custom-block"><p class="custom-block-title">Расплывчато</p><blockquote><p>Приведи эту таблицу в порядок.</p></blockquote></div><p>«Порядок» не определён: какие строки считать мусорными, можно ли менять исходный файл и что должно вернуться? Bot приходится угадывать трижды, прежде чем начать.</p><p><strong>Вместо этого:</strong></p><div class="tip custom-block"><p class="custom-block-title">Конкретно</p><blockquote><p>Удали из CSV, который я только что загрузил, все строки с пустой колонкой email. Отдай мне очищенный файл и скажи, сколько строк ты удалил. Исходный файл не изменяй.</p></blockquote></div><p>Общий приём в обеих переработках: назовите источники, ограничьте действия и сделайте результат проверяемым с одного взгляда.</p><h2 id="где-живут-правила" tabindex="-1">Где живут правила <a class="header-anchor" href="#где-живут-правила" aria-label="Permalink to &quot;Где живут правила&quot;">​</a></h2><p>Два вида указаний — два места:</p><ul><li><strong>Постоянные правила</strong> живут в инструкциях Bot на его странице деталей: роль, стандарты формата, постоянные ограничения. Они действуют в каждой будущей сессии.</li><li><strong>Разовые просьбы</strong> живут в сообщении: сегодняшний файл, исключение на этой неделе.</li></ul><p>Когда исправление должно закрепиться, повысьте его: сформулируйте как долговременное правило и перенесите в инструкции — ровно так, как показывает шаг 7 <a href="./quick-start.html#шаг-7-проверьте-результат-и-закрепите-правила">Быстрого старта</a>. Когда повторяется целый порядок действий, сохраните его как <a href="./skills.html">навык</a>, чтобы одна фраза его запускала; предпочтения, которые Bot должен вспоминать сам, отправляйте в <a href="./memory.html">память</a>.</p><h2 id="когда-разделять-bot" tabindex="-1">Когда разделять Bot <a class="header-anchor" href="#когда-разделять-bot" aria-label="Permalink to &quot;Когда разделять Bot&quot;">​</a></h2><p>Один Bot — одна задача. Bot с единственной чёткой задачей накапливает контекст, который продолжает ему помогать; Bot «на всё» размывает собственные инструкции и память. И <a href="./quick-start.html">Быстрый старт</a>, и <a href="./overview.html">Обзор</a> говорят то же самое, поэтому здесь только практический критерий: если у нового запроса другая аудитория, другие источники или ему нужны другие права, чем у текущей задачи Bot, — создайте второго Bot.</p><p>Каждый Bot получает собственные рабочее пространство, память, каналы и границу прав, и Bot не видят друг друга. Разделение к тому же делает права честными: Bot, который только читает заметки о релизах, никогда не нуждается в праве выполнять команды.</p><h2 id="подход-к-подтверждениям" tabindex="-1">Подход к подтверждениям <a class="header-anchor" href="#подход-к-подтверждениям" aria-label="Permalink to &quot;Подход к подтверждениям&quot;">​</a></h2><p>Давайте уровень, которого требует задача, и не больше: доступ к рабочему пространству разделён на ступени от чата через чтение, запись, выполнение до управления; см. <a href="./access.html">Контроль доступа</a>.</p><p>На практике:</p><ol><li>Начинайте новые рутины в режиме «только чтение», а вызовы инструментов записи и выполнения держите за подтверждением.</li><li>Просмотрите первые несколько запусков, прежде чем что-либо расширять.</li><li>Действия, покидающие рабочее пространство, — сообщения другим людям, всё внешнее — держите за подтверждением даже после того, как рутина кажется безопасной.</li></ol><p>Арифметика проста: подтвердить несколько запросов стоит куда дешевле, чем отменять ошибочную запись.</p><hr><h2 id="создание-bot" tabindex="-1">Создание Bot <a class="header-anchor" href="#создание-bot" aria-label="Permalink to &quot;Создание Bot&quot;">​</a></h2><ol><li>Перейдите на страницу <strong>Bots</strong> из боковой панели.</li><li>Нажмите кнопку <strong>Create Bot</strong>.</li><li>Заполните базовую информацию: <ul><li><strong>Display Name</strong>: имя, которое пользователи будут видеть в чатах.</li><li><strong>Avatar</strong>: URL изображения профиля Bot.</li><li><strong>Timezone</strong>: необязательный часовой пояс конкретного Bot. Если оставить пустым, Bot наследует часовой пояс пользователя или системы.</li><li><strong>ACL Preset</strong>: стартовая политика доступа, например <code>allow_all</code> или <code>private_only</code>.</li></ul></li><li>Нажмите <strong>Create</strong>.</li></ol><hr><h2 id="страница-detail-page" tabindex="-1">Страница Detail Page <a class="header-anchor" href="#страница-detail-page" aria-label="Permalink to &quot;Страница Detail Page&quot;">​</a></h2><p>После создания щелчок по карточке Bot ведёт на его страницу <strong>Detail Page</strong>, где весь его жизненный цикл управляется через специализированные вкладки.</p><h3 id="обзор-вкладок" tabindex="-1">Обзор вкладок <a class="header-anchor" href="#обзор-вкладок" aria-label="Permalink to &quot;Обзор вкладок&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Вкладка</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>Проверки состояния: рантайм рабочего пространства, база данных, каналы, память.</td></tr><tr><td><strong>General</strong></td><td>Основные настройки: модели чата/заголовков/изображений, привязки памяти/поиска/TTS, часовой пояс, язык, рассуждение и опасная зона.</td></tr><tr><td><strong>Desktop</strong></td><td>Рантайм дисплея рабочего пространства, доступность браузера с графическим интерфейсом (headed) и активные сессии дисплея.</td></tr><tr><td><strong>Workspace</strong></td><td>Жизненный цикл контейнерного рабочего пространства, снапшоты, экспорт и импорт данных.</td></tr><tr><td><strong>Network</strong></td><td>Сеть рабочего пространства и статус/действия overlay-провайдера.</td></tr><tr><td><strong>Memory</strong></td><td>Просмотр, поиск, создание, правка и сжатие воспоминаний.</td></tr><tr><td><strong>Platforms</strong></td><td>Конфигурации каналов: Telegram, Discord, Feishu, QQ, WeCom, WeChat, DingTalk, Web и другие.</td></tr><tr><td><strong>Access</strong></td><td>Правила ACL и поведение доступа по умолчанию.</td></tr><tr><td><strong>Tool Approval</strong></td><td>Настройки подтверждения человеком для инструментов, требующих согласия.</td></tr><tr><td><strong>Agents</strong></td><td>ACP-совместимые агенты для программирования, такие как Codex и Claude Code, которые можно включить для использования в чат-пространстве.</td></tr><tr><td><strong>Connectors</strong></td><td>Подключения сторонних сервисов (OAuth или API-ключ) через Connect-It: статус, включение/выключение, повторная авторизация, отключение.</td></tr><tr><td><strong>Hooks</strong></td><td>Правила автоматизации уровня Bot, хранящиеся в <code>/data/.memoh/hooks.json</code>.</td></tr><tr><td><strong>MCP</strong></td><td>Управление подключениями MCP (Stdio, Remote, OAuth).</td></tr><tr><td><strong>Compaction</strong></td><td>Настройки сжатия контекста сессий и журналы.</td></tr><tr><td><strong>Schedule</strong></td><td>Задачи по cron-расписанию и журналы выполнения.</td></tr><tr><td><strong>Skills</strong></td><td>Markdown-файлы навыков, задающие характер и возможности Bot.</td></tr></tbody></table><p>Files, Terminal и панели рабочего стола/браузера доступны также внутри чат-пространства — используйте сторону рабочего пространства в чате, когда хотите посмотреть файлы, выполнить команды оболочки или понаблюдать за браузером и рабочим столом Bot, не покидая диалог.</p><hr><h2 id="настроика-основных-параметров-bot" tabindex="-1">Настройка основных параметров Bot <a class="header-anchor" href="#настроика-основных-параметров-bot" aria-label="Permalink to &quot;Настройка основных параметров Bot&quot;">​</a></h2><p>После создания Bot самый важный шаг — настроить его рабочие параметры. Эти настройки разнесены по нескольким вкладкам, а не собраны в одну гигантскую форму.</p><ol><li>Перейдите на страницу <strong>Detail Page</strong> нужного Bot.</li><li>Начните с вкладки <strong>General</strong> — привязки чата и рантайма.</li><li>Вкладка <strong>Schedule</strong> — для повторяющихся автономных задач.</li><li>Вкладка <strong>Compaction</strong> — для поведения сжатия контекста сессий.</li><li>Вкладка <strong>Access</strong> — для уточнения правил ACL после начального ACL-пресета.</li></ol><p>Если вы ещё не создали эти ресурсы, сначала настройте их:</p><ul><li><a href="./../integrations/providers/llm.html">Провайдеры и модели</a></li><li><a href="./../integrations/providers/memory/builtin.html">Встроенный провайдер памяти</a></li><li><a href="./../integrations/providers/web-search.html">Провайдеры поиска</a></li><li><a href="./acp.html">Agents / ACP</a></li></ul><hr><h2 id="справочник-вкладки-general" tabindex="-1">Справочник вкладки General <a class="header-anchor" href="#справочник-вкладки-general" aria-label="Permalink to &quot;Справочник вкладки General&quot;">​</a></h2><p>Вкладка <strong>General</strong> содержит настройки, определяющие повседневное поведение в диалоге.</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Chat Model</strong></td><td>Основная LLM для генерации ответов в чате.</td></tr><tr><td><strong>Title Model</strong></td><td>Необязательная модель для генерации заголовков сессий.</td></tr><tr><td><strong>Image Generation Model</strong></td><td>Необязательная модель для функций генерации изображений. Выберите модель чата с поддержкой <code>image-output</code>.</td></tr><tr><td><strong>Memory Provider</strong></td><td>Бэкенд памяти, назначенный Bot. Встроенный провайдер может дополнительно определять собственные модели памяти и эмбеддингов.</td></tr><tr><td><strong>Search Provider</strong></td><td>Поисковая система для возможностей веб-поиска.</td></tr><tr><td><strong>TTS Model</strong></td><td>Необязательная речевая модель для синтеза речи. Речевые модели приходят из потока настройки TTS-провайдеров, а не из обычного потока провайдеров чата.</td></tr><tr><td><strong>Timezone</strong></td><td>Часовой пояс конкретного Bot. Если пусто, Memoh наследует часовой пояс пользователя, а если и он не задан — системный.</td></tr><tr><td><strong>Language</strong></td><td>Основной язык общения Bot.</td></tr><tr><td><strong>Reasoning Effort</strong></td><td>Доступно, когда выбранная модель чата объявляет совместимость <code>reasoning</code>. Варианты зависят от модели (например <code>low</code>, <code>medium</code>, <code>high</code>).</td></tr></tbody></table><p>Примечания:</p><ul><li><strong>Image Generation Model</strong> намеренно отделена от обычной модели чата, чтобы модель с поддержкой изображений можно было выделить только под задачи визуальной генерации.</li><li><strong>TTS Model</strong> приходит со страницы настроек <strong>Speech</strong> и использует модели <code>speech</code> настроенного речевого провайдера.</li><li><code>context_window</code> выбранной модели чата влияет на отчёт о статусе сессии и <a href="./compaction.html">сжатие контекста</a>.</li></ul><hr><h2 id="справочник-вкладки-compaction" tabindex="-1">Справочник вкладки Compaction <a class="header-anchor" href="#справочник-вкладки-compaction" aria-label="Permalink to &quot;Справочник вкладки Compaction&quot;">​</a></h2><p>Сжатие здесь — это <strong>сжатие контекста сессии</strong>, а не обслуживание памяти.</p><table tabindex="0"><thead><tr><th>Поле</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Compaction Enabled</strong></td><td>Включить или выключить автоматическое сжатие контекста.</td></tr><tr><td><strong>Compaction Threshold</strong></td><td>Оценочный порог в токенах, запускающий сжатие.</td></tr><tr><td><strong>Compaction Ratio</strong></td><td>Насколько агрессивно сокращать контекст сессии.</td></tr><tr><td><strong>Compaction Model</strong></td><td>Необязательная выделенная модель для суммирования старого контекста сессии.</td></tr></tbody></table><p>Вкладка <strong>Compaction</strong> также показывает журналы сжатия: недавние успешные, ожидающие и неудавшиеся запуски.</p><p>О поведении во время работы см. <a href="./compaction.html">Сжатие контекста</a>.</p><hr><h2 id="доступ-и-acl" tabindex="-1">Доступ и ACL <a class="header-anchor" href="#доступ-и-acl" aria-label="Permalink to &quot;Доступ и ACL&quot;">​</a></h2><p>При создании Bot стартует с <strong>ACL Preset</strong>. Дальше используйте вкладку <strong>Access</strong> для тонкого управления.</p><p>Важны два слоя:</p><ul><li><strong>ACL Preset</strong> даёт разумную стартовую политику для нового Bot.</li><li><strong>ACL Default Effect</strong> определяет результат по умолчанию, когда ни одно правило не совпало.</li></ul><p>Используйте вкладку <strong>Access</strong>, чтобы после начальной настройки уточнять правила для диалогов, групп и тредов.</p><hr><h2 id="продвинутые-настроики-связанные-с-discuss" tabindex="-1">Продвинутые настройки, связанные с Discuss <a class="header-anchor" href="#продвинутые-настроики-связанные-с-discuss" aria-label="Permalink to &quot;Продвинутые настройки, связанные с Discuss&quot;">​</a></h2><p>Большинству пользователей достаточно поведения <code>chat</code> и <code>discuss</code>, описанного в <a href="./sessions.html">Сессиях</a>.</p><p>Если вы управляете настройками Bot через API или собственную автоматизацию, схема настроек также включает <code>discuss_probe_model_id</code> для специфичных конфигураций режима discuss. Считайте это продвинутой настройкой, а не обязательным полем при обычном создании Bot.</p><hr><h2 id="фаилы-и-терминал-рабочего-пространства" tabindex="-1">Файлы и терминал рабочего пространства <a class="header-anchor" href="#фаилы-и-терминал-рабочего-пространства" aria-label="Permalink to &quot;Файлы и терминал рабочего пространства&quot;">​</a></h2><p>Файлы и терминалы рабочего пространства доступны из интерфейса чат-пространства, когда у Bot есть активный рантайм рабочего пространства. Оттуда можно:</p><ul><li>Просматривать и редактировать файлы в рабочем пространстве Bot.</li><li>Открывать терминальные сессии внутри рантайма рабочего пространства.</li><li>Пользоваться инструментами дисплея/браузера, когда у рабочего пространства Bot включена поддержка дисплея.</li></ul><p>О работе с файлами см. <a href="./files.html">Файлы</a>. О браузере с графическим интерфейсом и рабочем столе см. <a href="./browser-computer-use.html">Browser / Computer Use</a>.</p><hr><h2 id="удаление-bot" tabindex="-1">Удаление Bot <a class="header-anchor" href="#удаление-bot" aria-label="Permalink to &quot;Удаление Bot&quot;">​</a></h2><p>Чтобы безвозвратно удалить Bot и все связанные с ним данные (включая файлы рабочего пространства и память):</p><ol><li>Перейдите на вкладку <strong>General</strong> на странице деталей Bot.</li><li>Прокрутите до <strong>Danger Zone</strong> внизу.</li><li>Нажмите <strong>Delete Bot</strong> и подтвердите действие.</li></ol><blockquote><p><strong>Внимание</strong>: это действие необратимо. Все постоянные данные этого Bot будут потеряны.</p></blockquote>',76)])])}const u=o(s,[["render",l]]);export{p as __pageData,u as default};
